import React, { useState } from 'react';
import { TieredMenu } from 'primereact/tieredmenu';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="tieredMenu-accessibility">Accessible TieredMenu</label>
            <TieredMenu 
                id="tieredMenu-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible TieredMenu input"
                placeholder="Enter tieredMenu"
            />
        </div>
    );
}